PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,league TEXT NOT NULL,name TEXT NOT NULL,abbreviation TEXT UNIQUE NOT NULL,affiliate_team_id TEXT,conference TEXT,division TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS players(id TEXT PRIMARY KEY,nhl_player_id INTEGER UNIQUE,source_ids TEXT NOT NULL DEFAULT '{}',full_name TEXT NOT NULL,date_of_birth TEXT,age_at_start INTEGER,nationality TEXT,shoots_catches TEXT,primary_position TEXT,secondary_positions TEXT NOT NULL DEFAULT '[]',height_cm INTEGER,weight_kg INTEGER,real_team_id TEXT,level TEXT NOT NULL DEFAULT 'UNKNOWN',roster_status TEXT NOT NULL DEFAULT 'UNKNOWN',rights_owner_id TEXT,draft_year INTEGER,draft_round INTEGER,draft_overall INTEGER,jersey_number INTEGER,source_record_id INTEGER,confidence TEXT NOT NULL DEFAULT 'UNKNOWN',canon_status TEXT NOT NULL DEFAULT 'REAL_BASELINE',UNIQUE(full_name,date_of_birth));
CREATE TABLE IF NOT EXISTS contracts(id INTEGER PRIMARY KEY,player_id TEXT NOT NULL,team_id TEXT NOT NULL,start_season INTEGER,end_season INTEGER,cap_hit INTEGER,salary INTEGER,contract_type TEXT,one_two_way TEXT,expiry_status TEXT,qualifying_offer INTEGER,arbitration_eligible INTEGER NOT NULL DEFAULT 0,nmc INTEGER NOT NULL DEFAULT 0,ntc TEXT,retained_salary INTEGER NOT NULL DEFAULT 0,buried_cap INTEGER NOT NULL DEFAULT 0,verification_status TEXT NOT NULL DEFAULT 'UNKNOWN',canon_status TEXT NOT NULL DEFAULT 'REAL_BASELINE',source_record_id INTEGER,UNIQUE(player_id,team_id,start_season));
CREATE TABLE IF NOT EXISTS roster_assignments(id INTEGER PRIMARY KEY,simulation_id TEXT,player_id TEXT NOT NULL,team_id TEXT NOT NULL,league TEXT NOT NULL,status TEXT NOT NULL,role TEXT,line_no INTEGER,pair_no INTEGER,special_teams_role TEXT,start_date TEXT,end_date TEXT,simulation_status TEXT NOT NULL,UNIQUE(simulation_id,player_id,start_date));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_nhl_assignment ON roster_assignments(simulation_id,player_id) WHERE league='NHL' AND end_date IS NULL;
CREATE TABLE IF NOT EXISTS draft_picks(id INTEGER PRIMARY KEY,draft_year INTEGER NOT NULL,round INTEGER NOT NULL,original_owner_id TEXT NOT NULL,current_owner_id TEXT NOT NULL,overall_pick INTEGER,conditions TEXT,protection TEXT,status TEXT NOT NULL DEFAULT 'CONFIRMED',source_record_id INTEGER,canon_status TEXT NOT NULL DEFAULT 'REAL_BASELINE',UNIQUE(draft_year,round,original_owner_id));
CREATE TABLE IF NOT EXISTS draft_classes(player_id TEXT NOT NULL,draft_year INTEGER NOT NULL,classification TEXT NOT NULL CHECK(classification IN ('VERIFIED_REAL','EARLY_CANDIDATE','INCOMPLETE_SCOUTING','GENERATED_FUTURE_PROSPECT')),public_rank INTEGER,club TEXT,league TEXT,profile TEXT,potential TEXT,risk TEXT,nhl_eta TEXT,source_record_id INTEGER,PRIMARY KEY(player_id,draft_year));
CREATE TABLE IF NOT EXISTS draft_rankings(id INTEGER PRIMARY KEY,player_id TEXT,draft_year INTEGER,organization TEXT,scope TEXT,rank INTEGER,published_at TEXT,source_record_id INTEGER);
CREATE TABLE IF NOT EXISTS scouting_reports(id INTEGER PRIMARY KEY,simulation_id TEXT,player_id TEXT,method TEXT,scout_name TEXT,grade TEXT,potential_low TEXT,potential_high TEXT,risk TEXT,confidence TEXT,notes TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY,simulation_id TEXT,date TEXT,type TEXT NOT NULL,teams TEXT NOT NULL,players TEXT NOT NULL DEFAULT '[]',picks TEXT NOT NULL DEFAULT '[]',retained_salary INTEGER NOT NULL DEFAULT 0,conditions TEXT,source_record_id INTEGER,simulation_or_real TEXT NOT NULL,canon_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_state(id TEXT PRIMARY KEY,team_id TEXT NOT NULL,start_date TEXT NOT NULL,simulation_date TEXT NOT NULL,season TEXT NOT NULL,phase TEXT NOT NULL,day INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_players(simulation_id TEXT,player_id TEXT,team_id TEXT,level TEXT,status TEXT,morale INTEGER DEFAULT 70,form INTEGER DEFAULT 50,trade_block INTEGER DEFAULT 0,canon_status TEXT NOT NULL DEFAULT 'SIMULATION',PRIMARY KEY(simulation_id,player_id));
CREATE TABLE IF NOT EXISTS source_records(id INTEGER PRIMARY KEY,source TEXT NOT NULL,source_url TEXT NOT NULL,endpoint TEXT NOT NULL,fetched_at TEXT NOT NULL,verified_at TEXT,parser_version TEXT NOT NULL,confidence TEXT NOT NULL,payload_hash TEXT NOT NULL,overridden_by_canon INTEGER NOT NULL DEFAULT 0,UNIQUE(source_url,payload_hash));
CREATE TABLE IF NOT EXISTS data_conflicts(id INTEGER PRIMARY KEY,entity_type TEXT,entity_id TEXT,field TEXT,old_value TEXT,new_value TEXT,old_source TEXT,new_source TEXT,priority_old INTEGER,priority_new INTEGER,recommendation TEXT,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS canon_locks(id INTEGER PRIMARY KEY,simulation_id TEXT,entity_type TEXT,entity_id TEXT,field TEXT,locked_value TEXT,lock_type TEXT,reason TEXT,created_at TEXT,UNIQUE(simulation_id,entity_type,entity_id,field));
CREATE TABLE IF NOT EXISTS inbox(id INTEGER PRIMARY KEY,simulation_id TEXT,sender TEXT,subject TEXT,category TEXT,priority TEXT,deadline TEXT,content TEXT,actions TEXT,status TEXT DEFAULT 'UNREAD',created_at TEXT);
CREATE TABLE IF NOT EXISTS news(id INTEGER PRIMARY KEY,simulation_id TEXT,kind TEXT,headline TEXT,body TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS staff(id TEXT PRIMARY KEY,full_name TEXT,role TEXT,team_id TEXT,attributes TEXT,source_record_id INTEGER);
CREATE TABLE IF NOT EXISTS gm_profiles(team_id TEXT PRIMARY KEY,name TEXT,personality TEXT,risk_tolerance INTEGER,analytics INTEGER,relationship INTEGER DEFAULT 50,competitive_window TEXT,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS injuries(id INTEGER PRIMARY KEY,simulation_id TEXT,player_id TEXT,status TEXT,description TEXT,start_date TEXT,expected_return TEXT,source_record_id INTEGER);
CREATE TABLE IF NOT EXISTS waivers(id INTEGER PRIMARY KEY,simulation_id TEXT,player_id TEXT,status TEXT,placed_at TEXT,expires_at TEXT,claimed_by TEXT);
CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY,simulation_id TEXT,date TEXT,home_team TEXT,away_team TEXT,home_score INTEGER,away_score INTEGER,status TEXT);
CREATE TABLE IF NOT EXISTS player_game_stats(id INTEGER PRIMARY KEY,game_id INTEGER,player_id TEXT,goals INTEGER,assists INTEGER,shots INTEGER,toi_seconds INTEGER);
CREATE TABLE IF NOT EXISTS team_game_stats(id INTEGER PRIMARY KEY,game_id INTEGER,team_id TEXT,shots INTEGER,xg REAL,pp_goals INTEGER,pp_opportunities INTEGER);
CREATE TABLE IF NOT EXISTS simulation_events(id INTEGER PRIMARY KEY,simulation_id TEXT,event_date TEXT,event_type TEXT,payload TEXT,resolved INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS trade_negotiations(id INTEGER PRIMARY KEY,simulation_id TEXT,from_team TEXT,to_team TEXT,offer TEXT,status TEXT,interest INTEGER,deadline TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS verification_queue(id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,field TEXT NOT NULL,reason TEXT NOT NULL,source_url TEXT,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',UNIQUE(entity_type,entity_id,field,reason));
CREATE TABLE IF NOT EXISTS sync_runs(id TEXT PRIMARY KEY,started_at TEXT NOT NULL,finished_at TEXT,season TEXT NOT NULL,team_filter TEXT NOT NULL,dry_run INTEGER NOT NULL,status TEXT NOT NULL,summary TEXT);
CREATE TABLE IF NOT EXISTS season_roster_memberships(player_id TEXT NOT NULL,team_id TEXT NOT NULL,season TEXT NOT NULL,evidence TEXT NOT NULL,source_record_id INTEGER NOT NULL,PRIMARY KEY(player_id,team_id,season));
